const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    topic: body.topic || '¿Debemos expandirnos a Brasil este año o fortalecer primero los mercados actuales?',
    history: [],
    history_summary: null,
    round: 1,
    total_rounds: parseInt(body.total_rounds) || 3
  }
}];

const state = $input.first().json;
const nombre = 'Sofía Ramírez — CEO';
const rol = 'Visión estratégica y liderazgo';
const system_prompt = 'Eres Sofía Ramírez, CEO de una empresa de tecnología en crecimiento. Tu forma de pensar es siempre desde la visión de largo plazo. Escuchas a todos pero siempre rediriges la conversación hacia el impacto en el negocio: crecimiento y sostenibilidad. Eres directa y terminas con una pregunta para el grupo.';
const knowledge = 'Operamos en MX, CO y AR. Revenue: $8M. Objetivo: $15M en 2 años. Oportunidad en Brasil requiere inversión fuerte. Inversionistas abiertos a Serie B si hay estrategia clara.';

let historyText;
if (state.history_summary) {
  const currentRoundHistory = state.history
    .filter(h => h.round === state.round)
    .map(h => `[${h.nombre}]: ${h.response}`)
    .join('\n\n---\n\n');
  historyText = `[Resumen rondas anteriores]:\n${state.history_summary}` +
    (currentRoundHistory ? `\n\n[Esta ronda]:\n${currentRoundHistory}` : '');
} else if (state.history.length > 0) {
  historyText = state.history.map(h => `[${h.nombre} - Ronda ${h.round}]:\n${h.response}`).join('\n\n---\n\n');
} else {
  historyText = '(Eres la primera en hablar)';
}

const msg = `Contexto:\n${knowledge}\n\nTEMA: "${state.topic}"\nRonda: ${state.round} de ${state.total_rounds}\n\nHistorial:\n${historyText}\n\nResponde como CEO. Máximo 130 palabras.`;

const options = {
  method: 'POST',
  url: 'http://localhost:11434/api/chat',
  headers: { 'Content-Type': 'application/json' },
  body: { model: 'qwen3:14b', stream: false, messages:[{ role: 'system', content: system_prompt }, { role: 'user', content: msg }] },
  json: true
};

let res;
try {
  res = await this.helpers.httpRequest(options);
  state.history.push({ round: state.round, nombre, rol, response: res.message.content });
} catch(e) {
  state.history.push({ round: state.round, nombre, rol, response: `[ERROR ${nombre}: ${e.message}]` });
}
return [{ json: state }];

