const state = $input.first().json;

if (state.history.length === 0) return [{ json: state }];

const historialCompleto = state.history
  .map(h => `[${h.nombre} - Ronda ${h.round}]: ${h.response}`)
  .join('\n\n');

const options = {
  method: 'POST',
  url: 'http://localhost:11434/api/chat',
  headers: { 'Content-Type': 'application/json' },
  body: {
    model: 'llama3.2:latest',
    stream: false,
    messages: [
      { role: 'system', content: 'Eres un asistente que resume discusiones ejecutivas. Sé conciso y captura los puntos clave.' },
      { role: 'user', content: `Resume en máximo 5 bullets los puntos clave de esta discusión:\n\n${historialCompleto}` }
    ]
  },
  json: true
};

try {
  const res = await this.helpers.httpRequest(options);
  state.history_summary = res.message.content;
} catch(e) {
  state.history_summary = null;
}

return [{ json: state }];

const state = $input.first().json;
const fullDiscussion = state.history.map(h => `[${h.nombre} - Ronda ${h.round}]:\n${h.response}`).join('\n\n');

const msg = `Tema: "${state.topic}"\n\nDiscusión:\n${fullDiscussion}\n\n---\nEscribe una SÍNTESIS EJECUTIVA (Markdown) con:\n1. Consensos\n2. Tensiones y Riesgos\n3. Decisiones y Próximos pasos (30 días)`;

const options = {
  method: 'POST',
  url: 'http://localhost:11434/api/chat',
  headers: { 'Content-Type': 'application/json' },
  body: { model: 'qwen3:14b', stream: false, messages:[{ role: 'system', content: 'Eres analista estratégico experto en sintetizar discusiones ejecutivas.' }, { role: 'user', content: msg }] },
  json: true
};

let res;
try {
  res = await this.helpers.httpRequest(options);
  state.sintesis = res.message.content;
} catch(e) {
  state.sintesis = `[ERROR al generar síntesis: ${e.message}]`;
}
return [{ json: state }];

const state = $input.first().json;
const timestamp = new Date().toISOString().slice(0, 10);
const fileName = `Reporte_${timestamp}_${Date.now()}.md`;

let md = `# DISCUSIÓN ESTRATÉGICA
**Tema:** ${state.topic}
**Fecha:** ${new Date().toLocaleDateString()}

---

## SÍNTESIS EJECUTIVA
${state.sintesis}

---

## TRANSCRIPCIÓN COMPLETA DE LA SESIÓN
`;

for(const h of state.history) {
  md += `### ${h.nombre} (Ronda ${h.round})
> ${h.response}

`;
}

return [{
  json: { status: 'Completado', topic: state.topic, fileName },
  binary: {
    'Reporte_Estrategia': {
      data: Buffer.from(md, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: fileName,
      fileExtension: 'md'
    }
  }
}];
